package br.com.cineo;
import android.app.*;import android.content.*;import android.net.Uri;import android.widget.*;import android.view.*;import org.json.*;import java.io.*;import java.util.*;import static br.com.cineo.MainActivity.*;
/** Foreground queue. URI permissions and stable upload IDs survive app restarts. */
class UploadQueue {
 final MainActivity a;JSONObject selectedShow;int season=1,chapter=1;boolean running=false;String owner="";TextView progress;
 UploadQueue(MainActivity activity){a=activity;}
 JSONArray rows(){try{return new JSONArray(a.prefs.getString(a.local("upload_queue"),"[]"));}catch(Exception ex){return new JSONArray();}}
 void save(JSONArray rows){a.prefs.edit().putString(a.local("upload_queue"),rows.toString()).apply();}
 void form(JSONObject show){a.page("upload-queue-form","Enviar uma sequência",show.optString("title"),3,()->a.pro.studio(show));selectedShow=show;EditText s=a.field(a.body,"TEMPORADA","1",false),c=a.field(a.body,"PRIMEIRO CAPÍTULO","1",false);s.setInputType(2);c.setInputType(2);s.setText("1");c.setText("1");a.text(a.body,"Escolha vários MP4 de até 25 MB. Confira a ordem dos capítulos na fila antes de iniciar. Mantenha o aplicativo aberto durante o envio.",14,MUTED);a.button(a.body,"Selecionar vídeos",RED,()->a.safe(()->{season=Integer.parseInt(s.getText().toString());chapter=Integer.parseInt(c.getText().toString());if(season<1||chapter<1)throw new IOException("Use números maiores que zero.");Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("video/mp4");intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);a.startActivityForResult(intent,33);}));a.button(a.body,"Ver fila de envios",CARD,()->screen());}
 boolean result(int req,int res,Intent data){if(req!=33)return false;if(res!=Activity.RESULT_OK||data==null)return true;a.safe(()->{JSONArray queue=rows();ArrayList<Uri> uris=new ArrayList<>();if(data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());}else if(data.getData()!=null)uris.add(data.getData());for(Uri uri:uris){try{a.getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}String name="Episódio "+chapter;try(android.database.Cursor cursor=a.getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())name=cursor.getString(0).replaceFirst("(?i)\\.mp4$","");}queue.put(a.obj("upload_id",UUID.randomUUID().toString(),"show_id",selectedShow.getInt("id"),"show_title",selectedShow.optString("title"),"uri",uri.toString(),"season",season,"episode_number",chapter++,"title",name.substring(0,Math.min(100,name.length())),"status","pending","error",""));}save(queue);screen();});return true;}
 void screen(){a.page("upload-queue","Fila de envios","Os capítulos só são publicados após a aprovação necessária.",3,()->a.profile());a.text(a.body,running?"Envio em andamento. Mantenha o Cineo aberto.":"Confira a numeração e toque em Iniciar. Você pode repetir apenas os arquivos que falharam.",14,MUTED);progress=a.text(a.body,"",14,MUTED);JSONArray queue=rows();if(queue.length()==0)a.empty(a.body,"film","Sua fila está vazia","Escolha vários episódios no estúdio da produção.");for(int i=0;i<queue.length();i++){final int index=i;JSONObject row=queue.optJSONObject(i);a.title(a.body,"T"+row.optInt("season")+" · EP "+row.optInt("episode_number")+" — "+row.optString("title"),16);a.text(a.body,row.optString("show_title")+"\n"+state(row.optString("status"))+" "+row.optString("error"),12,MUTED);if(!running&&!row.optString("status").equals("done")){a.button(a.body,"Editar título e número",CARD,()->edit(index));a.button(a.body,"Cancelar este envio",CARD,()->a.safe(()->{JSONArray rows=rows();rows.remove(index);save(rows);screen();}));}}if(!running)a.button(a.body,"Iniciar / tentar falhas novamente",RED,()->start());else a.button(a.body,"Parar após o arquivo atual",CARD,()->{running=false;Toast.makeText(a,"A fila parará após este arquivo.",0).show();});}
 String state(String value){return value.equals("done")?"✓ Enviado":value.equals("failed")?"Falhou:":value.equals("uploading")?"Interrompido / em andamento":"Aguardando";}
 void edit(int index){JSONObject row=rows().optJSONObject(index);if(row==null)return;LinearLayout form=a.col();form.setPadding(a.dp(16),a.dp(12),a.dp(16),0);EditText title=a.field(form,"TÍTULO","",false),chapter=a.field(form,"CAPÍTULO","",false);title.setText(row.optString("title"));chapter.setInputType(2);chapter.setText(row.optString("episode_number"));new AlertDialog.Builder(a).setTitle("Organizar arquivo").setView(form).setNegativeButton("Cancelar",null).setPositiveButton("Salvar",(d,n)->a.safe(()->{JSONArray queue=rows();queue.getJSONObject(index).put("title",title.getText().toString()).put("episode_number",Integer.parseInt(chapter.getText().toString()));save(queue);screen();})).show();}
 void start(){if(running)return;JSONArray queue=rows();for(int i=0;i<queue.length();i++)try{if(queue.getJSONObject(i).optString("status").equals("failed-this-run"))queue.getJSONObject(i).put("status","failed");}catch(Exception ignored){}save(queue);running=true;owner=a.uid;screen();next();}
 void next(){if(!running||!owner.equals(a.uid))return;JSONArray queue=rows();int found=-1;for(int i=0;i<queue.length();i++)if(!queue.optJSONObject(i).optString("status").equals("done")&&!queue.optJSONObject(i).optString("status").equals("failed-this-run")){found=i;break;}if(found<0){running=false;for(int i=0;i<queue.length();i++)try{if(queue.getJSONObject(i).optString("status").equals("failed-this-run"))queue.getJSONObject(i).put("status","failed");}catch(Exception ignored){}save(queue);if(a.screen.equals("upload-queue"))screen();return;}final int index=found;JSONObject row=queue.optJSONObject(index);try{row.put("status","uploading");save(queue);}catch(Exception ignored){}if(progress!=null)progress.setText("Preparando "+row.optString("title"));final String token=a.token;final String account=owner;a.io.execute(()->{String error="";try{Uri uri=Uri.parse(row.getString("uri"));ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=a.getContentResolver().openInputStream(uri)){byte[] bytes=new byte[65536];int n;while((n=in.read(bytes))!=-1){if(out.size()+n>26214400)throw new IOException("MP4 acima de 25 MB.");out.write(bytes,0,n);}}JSONObject payload=new JSONObject(row.toString());payload.put("video",android.util.Base64.encodeToString(out.toByteArray(),2));int seconds=0;android.media.MediaMetadataRetriever metadata=new android.media.MediaMetadataRetriever();try{metadata.setDataSource(a,uri);String duration=metadata.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_DURATION);if(duration!=null)seconds=(int)(Long.parseLong(duration)/1000);}catch(Exception ignored){}finally{metadata.release();}payload.put("duration_seconds",seconds);if(!a.refresh.isEmpty()&&System.currentTimeMillis()/1000>a.expires-60)a.session(a.request("POST","/refresh",a.obj("refresh_token",a.refresh),""));a.request("POST","/v6/show/"+row.getInt("show_id")+"/upload",payload,a.token);}catch(Exception ex){error=ex.getMessage()==null?"Falha de conexão":ex.getMessage();}String failure=error;a.runOnUiThread(()->{if(a.isDestroyed()||!account.equals(a.uid)){running=false;return;}try{JSONArray current=rows();for(int i=0;i<current.length();i++){JSONObject item=current.getJSONObject(i);if(item.optString("upload_id").equals(row.optString("upload_id"))){item.put("status",failure.isEmpty()?"done":"failed-this-run").put("error",failure);break;}}save(current);}catch(Exception ignored){}if(a.screen.equals("upload-queue"))screen();if(running)next();});});}
}
